{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent increase cap","requirement":"A landlord may not raise rent more than 3% of the current rent or 80% of the CPI change, whichever is less; the maximum allowable increase is 2.87% for September 1, 2026 through August 31, 2027.","key_value":"2.87% for Sept 1, 2026 through Aug 31, 2027; otherwise 3% or 80% of CPI, whichever is less","coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-09-01","valid_through":"2027-08-31","citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"2.87 percent is the maximum allowable rent increase for the period of September 1, 2026 through August 31, 2027.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction requirement","requirement":"A landlord must have a valid reason to evict a tenant, such as nonpayment of rent, breaking the lease, or the landlord moving into the property; for certain reasons the landlord may have to pay relocation assistance.","key_value":null,"coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Santa Ana registration fee pass-through cap","requirement":"A landlord may charge the rental registration pass-through fee of at most $50 per rental unit per month; if the landlord charges more than $50, the landlord must reimburse the tenant for the overpayment. The fee is per unit, not per tenant.","key_value":"$50 per unit per month","coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Landlord must reimburse the tenant for any registration fee pass-through overpayment above $50.","effective_date":null,"valid_through":null,"citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"If a landlord charges a tenant a pass-through fee greater than $50, the landlord shall reimburse the tenant for the registration fee pass-through overpayment.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","n_rules":3,"note":null}

